package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.memory.*; import net.fabricmc.fabric.api.entity.FakePlayer; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import net.minecraft.world.entity.npc.villager.Villager; import net.minecraft.world.entity.animal.golem.IronGolem;
public final class VillagerGolemDefenseGameTest { @GameTest public void attackCreatesDefenseState(GameTestHelper c){Villager v=c.spawn(EntityTypes.VILLAGER,2,1,2);c.spawn(EntityTypes.IRON_GOLEM,5,1,2);var p=FakePlayer.get(c.getLevel());p.setPos(3,1,2);c.runAtTickTime(1,()->{TheWorldRemembers.handleDamage(v,c.getLevel().damageSources().playerAttack(p),1f,1f,false);if(MemoryManager.get(c.getLevel().getServer()).memoriesOf(v.getUUID()).stream().noneMatch(m->m.type()==MemoryEventType.PLAYER_ATTACKED_NPC)){c.fail("Attack was not remembered");return;}c.succeed();});}}
